  # Fingerprint only this page's assets, without rewriting unrelated files.
  def stamp(m):
   local=(path.parent/m[2]).resolve()
   if local.is_file():return m[1]+m[2]+'?v='+hashlib.sha256(local.read_bytes().replace(b'\r\n',b'\n')).hexdigest()[:8]+m[3]
   return m[0]
  output=re.sub(r'((?:src|href)=")([^"?]+\.(?:css|js))(")',stamp,output)
